import{_ as l,l as o,o as t,c as n,v as e,p as s,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"遗忘的度量","description":"","frontmatter":{"title":"遗忘的度量","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/forgetting-metrics.md","filePath":"llm/forgetting-metrics.md","lastUpdated":1789023840000}'),h={name:"llm/forgetting-metrics.md"};function m(c,a,_,f,g,A){const i=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="遗忘的度量" tabindex="-1">遗忘的度量 <a class="header-anchor" href="#遗忘的度量" aria-label="Permalink to &quot;遗忘的度量&quot;">​</a></h1><div class="epigraph"><p>训练损失升高不等于忘掉；拒答也不等于不可抽取。度量要分开：目标集上的可提取性、保留集上的效用、以及攻击换措辞后是否还在。</p><footer>—— 综合 Maini 等 TOFU（2024）、Li 等 WMDP（ICML 2024）、Eldan 与 Russinovich 的 Harry Potter 遗忘实验（2023）</footer></div><p>前几课已经在用「忘了」「还在」说话。<a href="/llm/continual-replay">回放</a>要旧任务回归；<a href="/llm/rmu-wmdp">RMU</a>要 WMDP 降、MMLU 留；<a href="/llm/rome-memit">ROME</a>要无关事实保持。本课把度量收成可写进配方的几栏，避免用单一准确率宣布成功。下一课<a href="/llm/negative-task-vector">负任务向量</a>仍用这套尺来验收算术遗忘。不发明新基准名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持续学习里的遗忘：任务 \\(T_i\\) 在学完 \\(T_{j\\gt i}\\) 之后的性能相对刚学完 \\(T_i\\) 时下降多少。隐私遗忘：攻击者能否从模型抽出 \\(D_f\\) 中的字符串或确认成员。能力遗忘：领域代理题是否仍会做。三种都叫 forgetting，曲线不可互换。用 MMLU 下降证明隐私遗忘，是用效用伤害冒充删除；用拒答率证明 WMDP 遗忘，是用接口冒充知识去掉。</p><p>Eldan 与 Russinovich 删除《哈利·波特》相关完成：表面问「霍格沃茨」会糊，换别名或补全诗句仍可能漏。度量必须含<strong>改写攻击集</strong>，否则只测了训练时见过的探针。</p><h3 id="对照模型几乎总是缺的" tabindex="-1">对照模型几乎总是缺的 <a class="header-anchor" href="#对照模型几乎总是缺的" aria-label="Permalink to &quot;对照模型几乎总是缺的&quot;">​</a></h3><p>TOFU 的优点是虚构传记，可与从未见过该传记的模型比。真实预训练数据没有「从未见过莎士比亚」的对照。只能用：抽取长度、成员推断 AUC、释义一致率、以及效用下限。不要报告「与精确遗忘只差 1%」除非真有对照。</p><p><span class="marginnote">成员推断（Shokri 等的攻击传统）在 LLM 上不稳定，但仍应作为一栏：有的方法降低填空却提高成员可分性，或相反。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一份遗忘卡，最少四栏：</p><ol><li><strong>目标失败</strong>：在 \\(D_f\\) 探针上，准确率 / 精确抽取率 / WMDP 分，应下降。含原文、释义、翻译、补全前缀。</li><li><strong>效用</strong>：声明的 \\(D_r\\) 与通用基准，相对遗忘前的相对下降上限（例如 2%）。</li><li><strong>流畅与格式</strong>：在<a href="/llm/chat-template">chat template</a> 下是否仍能对话，而不是进入乱码。乱码是破坏，不是遗忘。</li><li><strong>攻击残余</strong>：Best-of-N、角色扮演、把答案藏在代码注释里等你实际会面对的套取。只选与威胁模型相关的，但至少一类非原探针。</li></ol><p>持续学习另加：<strong>平均准确率</strong>与<strong>向后迁移</strong>（旧任务变化）、<strong>向前迁移</strong>（新任务是否受益）。报表不要只给平均值。</p>',13)),(t(),s(E,null,{default:r(()=>[d(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%9B%AE%E6%A0%87%E6%8E%A2%E9%92%88%20%2B%20%E6%94%B9%E5%86%99%22%5D%20--%3E%20DEC%5B%22%E5%8F%AF%E6%8F%90%E5%8F%96%E6%80%A7%22%5D%0A%20%20R%5B%22%E4%BF%9D%E7%95%99%E4%BB%BB%E5%8A%A1%20%2B%20%E9%80%9A%E7%94%A8%22%5D%20--%3E%20UTIL%5B%22%E6%95%88%E7%94%A8%22%5D%0A%20%20A%5B%22%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%E6%94%BB%E5%87%BB%22%5D%20--%3E%20RES%5B%22%E6%AE%8B%E4%BD%99%22%5D%0A%20%20DEC%20--%3E%20CARD%5B%22%E9%81%97%E5%BF%98%E5%8D%A1%22%5D%0A%20%20UTIL%20--%3E%20CARD%0A%20%20RES%20--%3E%20CARD%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>比较方法时用同一张卡。RMU、梯度上升、负任务向量、拒答 SFT 会在四栏上呈现不同轮廓：拒答常是 1 好、4 差；打乱权重常是 1 好、2–3 差。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「损失升高」只说明 \\(D_f\\) 上的平均 NLL 变差。模型仍可能用低熵的错误完成（改写成反事实）或把概率质量从原文挪到同义改写上——抽取失败、知识还在。故目标栏要生成式抽取，不只闭卷准确率。效用栏防止把模型推到随机初始化。攻击栏防止度量过拟合探针分布，这与 SFT 过拟合<a href="/llm/instruction-data-lineage">谱系</a>同构：你优化哪张表，哪张表就好看。</p><p>ROME 的局部性测试是遗忘卡在事实编辑上的特例：目标 / 邻近 / 流畅。应复用结构，换内容。</p><p><span class="marginnote">LoRA 卸载后四栏全回到基座，说明「遗忘」只存在于适配器。若合规要求针对基座，卡必须在卸载后测。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有单一标量可以排序所有遗忘方法。产品选定威胁模型后，对四栏做阈值约束，再在约束内优化计算。公开论文的数字依赖其探针；迁移到内部 \\(D_f\\) 必须重做卡。不要用本课指标去「证明」监管意义上的删除完成。下一课的任务算术在卡上往往表现为：目标任务掉、邻近任务若方向重叠也会掉，效用栏要写清哪些算 \\(D_r\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持续学习遗忘、隐私抽取、能力代理是三种度量，不可互相替代。</li><li>遗忘卡至少含：目标失败（含改写）、效用、流畅格式、攻击残余。</li><li>拒答与乱码都不是合格遗忘。</li><li>无对照模型时不要声称接近精确遗忘。</li><li>适配器方法须声明卸载后是否仍测。</li><li>出处：Maini 等，TOFU，2024；Li 等，WMDP，2024；Eldan 与 Russinovich，2023；ROME 的局部性评测结构。</li></ul>',9))])}const B=l(h,[["render",m]]);export{D as __pageData,B as default};
